<#
    Unit tests for Apply-OrgTemplate on generated projects (spec 2.9, 3.2 task 6, 5.3-5.5):
    the org dialog policy becomes DATA (AppConfig.json OrgUi) read by constant 'org-ui' blocks.

      * 4.1.8 and 4.2.0 Zero-Config projects (generated by Set-PSADTDataDrivenScript): org-ui blocks in
        Pre-Install, Pre-Uninstall, Pre-Repair, Post-Install, Post-Repair; no PSADT default dialog left
        outside toolkit blocks; both parsers clean; spec 5.3/5.4/5.5 reproduced byte-for-byte (4.2, hooks).
      * AppConfig.OrgUi + App.ScriptAuthor match the template; apostrophes round-trip as data; two
        templates with different dialog policies produce the SAME deploy script; re-apply is byte-identical.
      * fail closed before any write: '$Helpdesk' in dialog text -> W32T.OrgTemplateInvalid; strings.psd1
        anchor missing -> W32T.OrgTemplateDrift; the writer's 5.1 parse rejects the script (shadowed
        Test-Win32ToolkitPS51Syntax) -> W32T.GeneratedScriptInvalid; a psm1-only extension module ->
        W32T.OrgExtensionInvalid; legacy 1.1.6 / unpatched script -> W32T.UnsupportedTemplateShape -
        deploy script, config.psd1, strings.psd1 and AppConfig.json byte-identical.
      * typographic single quotes (U+2018/U+2019/U+201A/U+201B) in balloon / progress text round-trip
        through strings.psd1 (host + 5.1 parse); a config.psd1 / strings.psd1 text that is not one
        hashtable -> W32T.OrgTemplateInvalid before any write.

    Shadowed: Add-Win32ToolkitTemplateAssets, New-Win32ToolkitSparseConfig, Get-Win32ToolkitTemplateAssetFolder,
    Assert-Win32ToolkitOrgTemplateText (WP-D contract: a minimal D9 check), Test-Win32ToolkitPsadtVersionSupported (WP-A).

    Run:  pwsh -File Tests\OrgUiBlocks.unit.ps1
#>
# Test shadows keep the real command names and signatures (C-4: new files carry no PSSA warning).
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSReviewUnusedParameter', '', Justification = 'test shadows mirror the real signatures')]
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'test shadows and fixture builders')]
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns', '', Justification = 'test shadows keep the real command names')]
[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'
$repo = Split-Path -Parent $PSScriptRoot
$fail = 0
function Ok($m)  { Write-Host "  PASS: $m" -ForegroundColor Green }
function Bad($m) { Write-Host "  FAIL: $m" -ForegroundColor Red; $script:fail++ }

# C-5 range + WP-A contract shadow (spec 2.2).
$script:PsadtSupportedRange = [pscustomobject]@{ Min = [version]'4.1.0'; MaxExclusive = [version]'4.3.0'; Display = '4.1.x and 4.2.x' }
function Test-Win32ToolkitPsadtVersionSupported {
    param([Parameter(Position = 0)][object]$Version)
    if ($null -eq $script:PsadtSupportedRange) { throw [System.InvalidOperationException]::new('win32-toolkit internal error: PsadtSupportedRange is not initialised') }
    if ($null -eq $Version) { return $false }
    $v = $null
    if ($Version -is [version]) { $v = $Version } elseif (-not [version]::TryParse((([string]$Version) -split '-', 2)[0], [ref]$v)) { return $false }
    return ($v -ge $script:PsadtSupportedRange.Min -and $v -lt $script:PsadtSupportedRange.MaxExclusive)
}
foreach ($f in 'Get-Win32ToolkitDeployScriptShape', 'Set-Win32ToolkitPhaseBlock', 'Remove-Win32ToolkitPhaseBlock',
    'Remove-Win32ToolkitPhaseDefaultUi', 'Get-Win32ToolkitDeployScriptBlock', 'Write-Win32ToolkitDeployScript',
    'Test-Win32ToolkitPS51Syntax', 'Set-PSADTDataDrivenScript', 'Set-Win32ToolkitTextBlock', 'Apply-OrgTemplate',
    'Add-Win32ToolkitOrgHooks', 'Assert-Win32ToolkitOrgExtensionModule', 'Get-Win32ToolkitOrgExtensionLayoutFinding', 'Get-Win32ToolkitAppConfig', 'Set-Win32ToolkitAppConfig',
    'ConvertTo-PSSingleQuoted') {
    . (Join-Path $repo "Private\$f.ps1")
}

# -- shadows ---------------------------------------------------------------------------------------
function Add-Win32ToolkitTemplateAssets { param($ProjectPath, $Template, $BasePath) }
function New-Win32ToolkitSparseConfig { param($Template) "@{`r`n    Toolkit = @{`r`n        CompanyName = '$(ConvertTo-PSSingleQuoted ([string]$Template.CompanyName))'`r`n    }`r`n}`r`n" }
$script:ASSET = $null
function Get-Win32ToolkitTemplateAssetFolder { param([string]$TemplateName, [string]$BasePath) $script:ASSET }
# WP-D contract (spec 2.12) - minimal D9 rule for this suite: no '$' expansion in dialog text.
function Assert-Win32ToolkitOrgTemplateText {
    param($Template, [string]$Context)
    $fields = @($Template.CompanyName, $Template.ProgressDialog.StatusMessage, $Template.ProgressDialog.StatusMessageDetail, $Template.CompletionPrompt.Message)
    if (@($fields | Where-Object { "$_" -match '\$[\w{(:?$^]' }).Count) {
        throw [System.Management.Automation.ErrorRecord]::new([System.InvalidOperationException]::new("Org template text is invalid ($Context)."),
            'W32T.OrgTemplateInvalid', [System.Management.Automation.ErrorCategory]::InvalidData, $Template)
    }
}

$TMP = Join-Path ([System.IO.Path]::GetTempPath()) ('w32ou_' + [guid]::NewGuid().ToString('N').Substring(0, 6))
New-Item -ItemType Directory -Path $TMP -Force | Out-Null
# Scratch template asset folder with three hook files (for the spec 5.3-5.5 layouts).
$script:ASSET = Join-Path $TMP 'Templates\Contoso'
New-Item -ItemType Directory -Path (Join-Path $script:ASSET 'Hooks') -Force | Out-Null
foreach ($h in 'PreInstall.ps1', 'PostInstall.ps1', 'PostUninstall.ps1') { Set-Content -LiteralPath (Join-Path $script:ASSET "Hooks\$h") -Value "Write-ADTLogEntry -Message 'hook'" -Encoding UTF8 }

$stringsPsd1 = @'
@{
    BalloonTip = @{
        # Text displayed in the balloon tip for successful completion of a deployment type.
        Complete = @{
            Install = 'Installation complete.'
            Repair = 'Repair complete.'
            Uninstall = 'Uninstallation complete.'
        }
    }

    ProgressPrompt = @{
        # Default message displayed in the progress bar.
        Message = @{
            Install = 'Installation in progress.'
            Repair = 'Repair in progress.'
            Uninstall = 'Uninstallation in progress.'
        }
    }

    RestartPrompt = @{
        Message = 'Please restart.'
    }
}
'@

function New-Project([string]$Fixture, [string]$Label, [switch]$NoGenerate) {
    $p = Join-Path $TMP $Label
    foreach ($d in 'Config', 'Strings', 'SupportFiles') { New-Item -ItemType Directory -Path (Join-Path $p $d) -Force | Out-Null }
    $bom = New-Object System.Text.UTF8Encoding($true)
    [System.IO.File]::WriteAllText((Join-Path $p 'Config\config.psd1'), "@{`r`n    Toolkit = @{ CompanyName = 'PSAppDeployToolkit' }`r`n}`r`n", $bom)
    [System.IO.File]::WriteAllText((Join-Path $p 'Strings\strings.psd1'), (($stringsPsd1 -replace "`r?`n", "`r`n") + "`r`n"), $bom)
    $app = [pscustomobject]@{ SchemaVersion = '1.0'; App = [pscustomobject]@{ Vendor = 'Contoso'; Name = 'Tool'; DisplayName = 'Tool'; Version = '1.0'; Arch = 'x64'; ScriptAuthor = 'old'; ScriptDate = '2026-10-15' } }
    $null = Set-Win32ToolkitAppConfig -ProjectPath $p -Config $app
    Copy-Item -LiteralPath (Join-Path $repo "Tests\Fixtures\$Fixture\Invoke-AppDeployToolkit.ps1") -Destination (Join-Path $p 'Invoke-AppDeployToolkit.ps1')
    if (-not $NoGenerate) { $null = Set-PSADTDataDrivenScript -ScriptPath (Join-Path $p 'Invoke-AppDeployToolkit.ps1') -WarningAction SilentlyContinue }
    return $p
}
function New-Template([hashtable]$Override = @{}) {
    $t = [ordered]@{
        TemplateName           = 'Contoso'
        CompanyName            = 'Contoso'
        AppScriptAuthor        = "O'Brien IT"
        BalloonComplete        = [pscustomobject]@{ Install = 'Done.'; Repair = 'Repaired.'; Uninstall = 'Removed.' }
        ProgressMessage        = [pscustomobject]@{ Install = 'Installing.'; Repair = 'Repairing.'; Uninstall = 'Removing.' }
        ProgressMessageDetail  = [pscustomobject]@{ Install = 'Wait.'; Repair = 'Wait.'; Uninstall = 'Wait.' }
        WelcomeDialog          = [pscustomobject]@{ Enabled = $true; AllowDefer = $true; DeferTimes = 3; CheckDiskSpace = $false; PersistPrompt = $true; BlockExecution = $true; CloseProcessesCountdown = 180 }
        UninstallWelcomeDialog = [pscustomobject]@{ Enabled = $true; CloseProcessesCountdown = 60; PersistPrompt = $false; BlockExecution = $false }
        ProgressDialog         = [pscustomobject]@{ Enabled = $true; StatusMessage = "Don't switch off"; StatusMessageDetail = '' }
        CompletionPrompt       = [pscustomobject]@{ Enabled = $true; Message = "It's installed."; ButtonRightText = 'OK' }
        Hooks                  = [pscustomobject]@{ Enabled = $false; FailureAction = 'Fail' }
        ExtensionModule        = $false
    }
    foreach ($k in $Override.Keys) { $t[$k] = $Override[$k] }
    [pscustomobject]$t
}
function Get-Text([string]$Path) { ([System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)) -replace "`r`n", "`n" }
function Get-ProjectHash([string]$Proj) {
    @('Invoke-AppDeployToolkit.ps1', 'Config\config.psd1', 'Strings\strings.psd1', 'SupportFiles\AppConfig.json') |
        ForEach-Object { (Get-FileHash -LiteralPath (Join-Path $Proj $_) -Algorithm SHA256).Hash }
}
function Invoke-Apply([string]$Proj, $Template) {
    $wv = $null
    try { $r = Apply-OrgTemplate -ProjectPath $Proj -Template $Template -WarningVariable wv -WarningAction SilentlyContinue 6>$null; [pscustomobject]@{ Result = $r; Fqid = ''; Message = ''; Warnings = @($wv) } }
    catch { [pscustomobject]@{ Result = $null; Fqid = $_.FullyQualifiedErrorId; Message = $_.Exception.Message; Warnings = @($wv) } }
}

# -- [1] org-ui blocks, PSADT defaults gone --------------------------------------------------------
Write-Host '[1] org-ui blocks in the five phases; no PSADT default dialog outside toolkit blocks' -ForegroundColor Cyan
$projects = @{}
foreach ($g in 'psadt-4.1.8', 'psadt-4.2.0-zeroconfig') {
    $p = New-Project $g "ok-$g"
    $r = Invoke-Apply $p (New-Template)
    if ($r.Result -eq $true -and $r.Warnings.Count -eq 0) { Ok "$g : Apply-OrgTemplate returned `$true without warnings" } else { Bad "$g : result=$($r.Result) $($r.Fqid) $($r.Message) warnings=[$($r.Warnings -join '; ')]" }
    $t = Get-Text (Join-Path $p 'Invoke-AppDeployToolkit.ps1')
    $sh = Get-Win32ToolkitDeployScriptShape -Content $t -IncludeLayout
    $ui = @($sh.Layout.Blocks | Where-Object Slot -eq 'org-ui' | ForEach-Object Phase | Sort-Object)
    if (($ui -join ',') -eq 'Post-Install,Post-Repair,Pre-Install,Pre-Repair,Pre-Uninstall') { Ok "$g : org-ui block in Pre-Install, Pre-Uninstall, Pre-Repair, Post-Install, Post-Repair" } else { Bad "$g : org-ui in [$($ui -join ',')]" }
    $ast = [System.Management.Automation.Language.Parser]::ParseInput($t, [ref]$null, [ref]$null)
    $outside = @($ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -like 'Show-ADT*' }, $true) |
            Where-Object { $o = $_.Extent.StartOffset; -not ($sh.Layout.Blocks | Where-Object { $o -ge $_.Start -and $o -lt $_.End }) })
    if ($outside.Count -eq 0 -and $t -notmatch '\$saiwParams') { Ok "$g : no Show-ADT* call / `$saiwParams outside toolkit blocks" } else { Bad "$g : left: $(($outside | ForEach-Object { $_.Extent.Text }) -join ' | ')" }
    $errs = $null; [void][System.Management.Automation.Language.Parser]::ParseFile((Join-Path $p 'Invoke-AppDeployToolkit.ps1'), [ref]$null, [ref]$errs)
    $ps51 = @(Test-Win32ToolkitPS51Syntax -Path (Join-Path $p 'Invoke-AppDeployToolkit.ps1'))
    if (@($errs).Count -eq 0 -and $ps51.Count -eq 0 -and $sh.Support -eq 'Supported' -and $sh.GeneratorVersion -eq 2) { Ok "$g : host + 5.1 parse clean, still Supported / GeneratorVersion 2" } else { Bad "$g : host=$(@($errs).Count) 5.1=$($ps51.Count) $($sh.Support)" }
    if (-not $t.Contains("O'Brien IT") -and -not $t.Contains("Don't switch off") -and -not $t.Contains("It's installed.")) { Ok "$g : no template value spliced into the deploy script" } else { Bad "$g : a template value reached the deploy script" }
    $projects[$g] = $p
}

# -- [2] AppConfig data ----------------------------------------------------------------------------
Write-Host '[2] AppConfig.json carries the dialog policy (OrgUi) and App.ScriptAuthor as DATA' -ForegroundColor Cyan
$cfg = Get-Win32ToolkitAppConfig -ProjectPath $projects['psadt-4.2.0-zeroconfig']
$o = $cfg.OrgUi
$okWelcome = $o.Welcome.Enabled -eq $true -and $o.Welcome.AllowDefer -eq $true -and $o.Welcome.DeferTimes -eq 3 -and $o.Welcome.CheckDiskSpace -eq $false -and
    $o.Welcome.PersistPrompt -eq $true -and $o.Welcome.BlockExecution -eq $true -and $o.Welcome.CloseProcessesCountdown -eq 180
$okUninst = $o.UninstallWelcome.Enabled -eq $true -and $o.UninstallWelcome.CloseProcessesCountdown -eq 60 -and $o.UninstallWelcome.PersistPrompt -eq $false -and $o.UninstallWelcome.BlockExecution -eq $false
$okRest = $o.Progress.Enabled -eq $true -and $o.Progress.StatusMessage -ceq "Don't switch off" -and $o.Completion.Enabled -eq $true -and
    $o.Completion.Message -ceq "It's installed." -and $o.Completion.ButtonRightText -eq 'OK' -and $o.SchemaVersion -eq '1.0'
if ($okWelcome -and $okUninst -and $okRest) { Ok 'OrgUi matches the template (Welcome, UninstallWelcome, Progress, Completion); apostrophes round-trip as data' } else { Bad ($o | ConvertTo-Json -Depth 4) }
if ($cfg.App.ScriptAuthor -ceq "O'Brien IT" -and $cfg.App.Vendor -eq 'Contoso' -and $cfg.App.Version -eq '1.0') { Ok 'App.ScriptAuthor written from the template; other App fields preserved' } else { Bad ($cfg.App | ConvertTo-Json) }
if (-not $o.Welcome.PSObject.Properties['CustomText']) { Ok 'WelcomeDialog.CustomText is not carried (dead option, ORG-11)' } else { Bad 'CustomText carried' }

$p = New-Project 'psadt-4.2.0-zeroconfig' 'no-uwd'
$tpl = New-Template; $tpl.PSObject.Properties.Remove('UninstallWelcomeDialog')
$null = Invoke-Apply $p $tpl
$u = (Get-Win32ToolkitAppConfig -ProjectPath $p).OrgUi.UninstallWelcome
if ($u.Enabled -eq $true -and $u.CloseProcessesCountdown -eq 60 -and $u.PersistPrompt -eq $false -and $u.BlockExecution -eq $false) { Ok 'a template without UninstallWelcomeDialog gets the Update-OrgTemplateIfNeeded defaults' } else { Bad ($u | ConvertTo-Json) }

# -- [3] the policy is data: same script for different policies; re-apply idempotent ----------------
Write-Host '[3] dialog policy is data; re-apply is byte-identical' -ForegroundColor Cyan
foreach ($g in $projects.Keys) {
    $p = $projects[$g]
    $h1 = Get-ProjectHash $p
    $r = Invoke-Apply $p (New-Template)
    if ($r.Result -eq $true -and ((Get-ProjectHash $p) -join ',') -eq ($h1 -join ',')) { Ok "$g : re-apply -> deploy script, config.psd1, strings.psd1, AppConfig.json byte-identical" } else { Bad "$g : re-apply changed a file ($($r.Fqid))" }
    $before = Get-Text (Join-Path $p 'Invoke-AppDeployToolkit.ps1')
    $other = New-Template @{ WelcomeDialog = [pscustomobject]@{ Enabled = $false }; CompletionPrompt = [pscustomobject]@{ Enabled = $false; Message = ''; ButtonRightText = '' }; ProgressDialog = [pscustomobject]@{ Enabled = $false } }
    $null = Invoke-Apply $p $other
    $after = Get-Text (Join-Path $p 'Invoke-AppDeployToolkit.ps1')
    $cfg2 = Get-Win32ToolkitAppConfig -ProjectPath $p
    if ($after -ceq $before -and $cfg2.OrgUi.Welcome.Enabled -eq $false -and $cfg2.OrgUi.Completion.Enabled -eq $false) { Ok "$g : another dialog policy changes only AppConfig.OrgUi, not the script" } else { Bad "$g : the script changed with the policy" }
    $null = Invoke-Apply $p (New-Template)
}

# -- [4] spec 5.3 / 5.4 / 5.5 byte-for-byte (4.2 Zero-Config, hooks Fail) --------------------------
Write-Host '[4] spec 5.3 / 5.4 / 5.5 phases reproduced byte-for-byte (4.2 Zero-Config with hooks)' -ForegroundColor Cyan
$p = New-Project 'psadt-4.2.0-zeroconfig' 'spec5'
$null = Invoke-Apply $p (New-Template @{ Hooks = [pscustomobject]@{ Enabled = $true; FailureAction = 'Fail' } })
$t = Get-Text (Join-Path $p 'Invoke-AppDeployToolkit.ps1')
function Get-Phase([string]$Text, [string]$Name) {
    $a = $Text.IndexOf("New-Variable -Name $Name -Force -Value {`n"); $b = $Text.IndexOf("`n}`n", $a) + 3
    $Text.Substring($a, $b - $a)
}
$expPre = @'
New-Variable -Name Pre-Install -Force -Value {
    ## win32-toolkit:Pre-Install:org-ui (begin) - managed by win32-toolkit; regenerated, do not edit inside
    ## Org template dialogs - policy is DATA in SupportFiles\AppConfig.json (OrgUi); nothing is spliced here.
    ## PSADT 4.2 note: DeployMode Auto resolves to Silent when no listed process is running (or the list is
    ## empty), so these dialogs only show when the user must close an app.
    $w32tUi = $appConfig.OrgUi
    if ($w32tUi -and $w32tUi.Welcome -and $w32tUi.Welcome.Enabled) {
        $w32tWelcome = @{}
        if ($w32tUi.Welcome.AllowDefer) {
            $w32tWelcome['AllowDefer'] = $true
            if ([int]$w32tUi.Welcome.DeferTimes -gt 0) { $w32tWelcome['DeferTimes'] = [int]$w32tUi.Welcome.DeferTimes }
        }
        if ($w32tUi.Welcome.CheckDiskSpace) { $w32tWelcome['CheckDiskSpace'] = $true }
        if ($w32tUi.Welcome.PersistPrompt) { $w32tWelcome['PersistPrompt'] = $true }
        if ($adtSession.AppProcessesToClose.Count -gt 0) {
            $w32tWelcome['CloseProcesses'] = $adtSession.AppProcessesToClose
            if ($w32tUi.Welcome.BlockExecution) { $w32tWelcome['BlockExecution'] = $true }
            $w32tCountdown = [int]$w32tUi.Welcome.CloseProcessesCountdown
            if ($w32tCountdown -gt 0 -and $w32tCountdown -le 86400) { $w32tWelcome['CloseProcessesCountdown'] = $w32tCountdown }
        }
        Show-ADTInstallationWelcome @w32tWelcome
    }
    if ($w32tUi -and $w32tUi.Progress -and $w32tUi.Progress.Enabled) {
        $w32tProgress = @{}
        if (-not [string]::IsNullOrWhiteSpace([string]$w32tUi.Progress.StatusMessage)) { $w32tProgress['StatusMessage'] = [string]$w32tUi.Progress.StatusMessage }
        if (-not [string]::IsNullOrWhiteSpace([string]$w32tUi.Progress.StatusMessageDetail)) { $w32tProgress['StatusMessageDetail'] = [string]$w32tUi.Progress.StatusMessageDetail }
        Show-ADTInstallationProgress @w32tProgress
    }
    ## win32-toolkit:Pre-Install:org-ui (end)
    ## win32-toolkit:Pre-Install:hook (begin) - managed by win32-toolkit; regenerated, do not edit inside
    ## Org hook Pre-Install: runs SupportFiles\OrgHooks\PreInstall.ps1 when present (edit that file, not this block).
    $orgHookScript = Join-Path -Path $adtSession.DirSupportFiles -ChildPath 'OrgHooks\PreInstall.ps1'
    if (Test-Path -LiteralPath $orgHookScript) { . $orgHookScript }
    ## win32-toolkit:Pre-Install:hook (end)
}
'@ -replace "`r`n", "`n" | ForEach-Object { $_ + "`n" }
$expPost = @'
New-Variable -Name Post-Install -Force -Value {
    ## win32-toolkit:Post-Install:hook (begin) - managed by win32-toolkit; regenerated, do not edit inside
    ## Org hook Post-Install: runs SupportFiles\OrgHooks\PostInstall.ps1 when present (edit that file, not this block).
    $orgHookScript = Join-Path -Path $adtSession.DirSupportFiles -ChildPath 'OrgHooks\PostInstall.ps1'
    if (Test-Path -LiteralPath $orgHookScript) { . $orgHookScript }
    ## win32-toolkit:Post-Install:hook (end)
    ## win32-toolkit:Post-Install:tattoo (begin) - managed by win32-toolkit; regenerated, do not edit inside
    ## win32-toolkit install tattoo - records install state + version for the Intune detection rule.
    ## Written only when the Install phase reached its end ($w32tInstallDone, set by the install-done block).
    $w32tName = if ($appConfig.App.DisplayName) { $appConfig.App.DisplayName } else { $appConfig.App.Name }
    if (-not $w32tInstallDone) {
        Write-ADTLogEntry -Message 'win32-toolkit: the Install phase did not run to its end - the detection tattoo was NOT written.' -Severity 2
    }
    elseif ($w32tName -and $appConfig.App.Vendor -and $appConfig.App.Version -and $appConfig.App.ScriptAuthor) {
        Set-ADTRegistryKey -Key "HKLM:\SOFTWARE\$($appConfig.App.ScriptAuthor)\$($appConfig.App.Vendor)\$w32tName" -Name 'Version' -Value "$($appConfig.App.Version)" -Type 'String'
    }
    ## win32-toolkit:Post-Install:tattoo (end)
    ## win32-toolkit:Post-Install:org-ui (begin) - managed by win32-toolkit; regenerated, do not edit inside
    ## Org template completion prompt - policy is DATA in AppConfig.json (OrgUi.Completion). Never shown for a
    ## Zero-Config MSI (4.1.8 parity: the PSADT 4.2 template prompts unconditionally).
    $w32tUi = $appConfig.OrgUi
    if ($w32tUi -and $w32tUi.Completion -and $w32tUi.Completion.Enabled -and -not $adtSession.UseDefaultMsi -and
        -not [string]::IsNullOrWhiteSpace([string]$w32tUi.Completion.Message)) {
        $w32tButton = [string]$w32tUi.Completion.ButtonRightText
        if ([string]::IsNullOrWhiteSpace($w32tButton)) { $w32tButton = 'OK' }
        Show-ADTInstallationPrompt -Message ([string]$w32tUi.Completion.Message) -ButtonRightText $w32tButton -NoWait
    }
    ## win32-toolkit:Post-Install:org-ui (end)
}
'@ -replace "`r`n", "`n" | ForEach-Object { $_ + "`n" }
$expPostUninstall = @'
New-Variable -Name Post-Uninstall -Force -Value {
    ## win32-toolkit:Post-Uninstall:hook (begin) - managed by win32-toolkit; regenerated, do not edit inside
    ## Org hook Post-Uninstall: runs SupportFiles\OrgHooks\PostUninstall.ps1 when present (edit that file, not this block).
    $orgHookScript = Join-Path -Path $adtSession.DirSupportFiles -ChildPath 'OrgHooks\PostUninstall.ps1'
    if (Test-Path -LiteralPath $orgHookScript) { . $orgHookScript }
    ## win32-toolkit:Post-Uninstall:hook (end)
    ## win32-toolkit:Post-Uninstall:tattoo (begin) - managed by win32-toolkit; regenerated, do not edit inside
    ## win32-toolkit install tattoo - remove the key written during install.
    $w32tName = if ($appConfig.App.DisplayName) { $appConfig.App.DisplayName } else { $appConfig.App.Name }
    if ($w32tName -and $appConfig.App.Vendor -and $appConfig.App.ScriptAuthor) {
        $w32tTattooKey = "HKLM:\SOFTWARE\$($appConfig.App.ScriptAuthor)\$($appConfig.App.Vendor)\$w32tName"
        Remove-ADTRegistryKey -Key $w32tTattooKey -Recurse
        ## Legacy cleanup: packages published with the old 'powershell.exe -File' command line ran 32-bit under
        ## the Intune Management Extension and wrote the tattoo under WOW6432Node. Remove that copy too - only
        ## when it exists: Remove-ADTRegistryKey logs a warning for an absent key, the normal case since the
        ## exe launcher.
        $w32tLegacyKey = "HKLM:\SOFTWARE\WOW6432Node\$($appConfig.App.ScriptAuthor)\$($appConfig.App.Vendor)\$w32tName"
        if ([System.Environment]::Is64BitProcess -and (Test-Path -LiteralPath $w32tLegacyKey)) {
            Remove-ADTRegistryKey -Key $w32tTattooKey -Wow6432Node -Recurse
        }
    }
    ## win32-toolkit:Post-Uninstall:tattoo (end)
}
'@ -replace "`r`n", "`n" | ForEach-Object { $_ + "`n" }
$expPostRepair = "New-Variable -Name Post-Repair -Force -Value {`n    ## win32-toolkit:Post-Repair:org-ui (begin) - managed by win32-toolkit; regenerated, do not edit inside`n    ## Org template policy: no completion prompt after a repair (the PSADT default prompt was removed).`n    ## win32-toolkit:Post-Repair:org-ui (end)`n}`n"
foreach ($c in @(@{ N = 'Pre-Install (spec 5.3)'; P = 'Pre-Install'; E = $expPre }, @{ N = 'Post-Install (spec 5.4)'; P = 'Post-Install'; E = $expPost },
        @{ N = 'Post-Uninstall (spec 5.5)'; P = 'Post-Uninstall'; E = $expPostUninstall }, @{ N = 'Post-Repair (spec 5.4)'; P = 'Post-Repair'; E = $expPostRepair })) {
    $got = Get-Phase $t $c.P
    if ($got -ceq $c.E) { Ok "$($c.N) byte-for-byte" } else { Bad "$($c.N) differs:`n$got" }
}
$pu = Get-Phase $t 'Pre-Uninstall'
if ($pu.Contains('$w32tUi.UninstallWelcome.Enabled -and $adtSession.AppProcessesToClose.Count -gt 0') -and (Get-Phase $t 'Pre-Repair').Contains('$w32tUi.UninstallWelcome.Enabled')) {
    Ok 'Pre-Uninstall and Pre-Repair use the maintenance (UninstallWelcome) policy'
} else { Bad 'maintenance welcome missing' }

# -- [5] fail closed before any write --------------------------------------------------------------
Write-Host '[5] fail closed before any write' -ForegroundColor Cyan
$p = New-Project 'psadt-4.2.0-zeroconfig' 'bad-text'
$h = Get-ProjectHash $p
$r = Invoke-Apply $p (New-Template @{ CompletionPrompt = [pscustomobject]@{ Enabled = $true; Message = 'Call $Helpdesk'; ButtonRightText = 'OK' } })
if ($r.Fqid -eq 'W32T.OrgTemplateInvalid' -and ((Get-ProjectHash $p) -join ',') -eq ($h -join ',')) { Ok "'`$Helpdesk' in dialog text -> W32T.OrgTemplateInvalid, nothing written" } else { Bad "fqid='$($r.Fqid)' $($r.Message)" }

$p = New-Project 'psadt-4.2.0-zeroconfig' 'drift'
$sp = Join-Path $p 'Strings\strings.psd1'
[System.IO.File]::WriteAllText($sp, ([System.IO.File]::ReadAllText($sp)).Replace('    RestartPrompt = @{', '    RebootPrompt = @{'), (New-Object System.Text.UTF8Encoding($true)))
$h = Get-ProjectHash $p
$r = Invoke-Apply $p (New-Template)
if ($r.Fqid -eq 'W32T.OrgTemplateDrift' -and $r.Message -match 'progress-prompt' -and ((Get-ProjectHash $p) -join ',') -eq ($h -join ',')) { Ok 'strings.psd1 anchor removed -> W32T.OrgTemplateDrift, nothing written' } else { Bad "fqid='$($r.Fqid)' $($r.Message)" }

# The writer's 5.1 parse is the only output validation: when it rejects the script, config.psd1,
# strings.psd1 and AppConfig.json must not have been rewritten either.
$p = New-Project 'psadt-4.2.0-zeroconfig' 'ps51-reject'
$h = Get-ProjectHash $p
function Test-Win32ToolkitPS51Syntax { param([string]$Path) @('synthetic 5.1 parse error') }
try { $r = Invoke-Apply $p (New-Template) }
finally { . (Join-Path $repo 'Private\Test-Win32ToolkitPS51Syntax.ps1') }
if ($r.Fqid -eq 'W32T.GeneratedScriptInvalid' -and $r.Message -match 'synthetic 5\.1 parse error' -and ((Get-ProjectHash $p) -join ',') -eq ($h -join ',')) {
    Ok '5.1 parse rejected -> W32T.GeneratedScriptInvalid; deploy script, config.psd1, strings.psd1, AppConfig.json byte-identical'
} else { Bad "fqid='$($r.Fqid)' $($r.Message) changed=[$(@(0..3 | Where-Object { (Get-ProjectHash $p)[$_] -ne $h[$_] }) -join ',')]" }

# A broken extension module is an INPUT error: it must stop Apply before the first write (ps-quality-01),
# not after config.psd1, strings.psd1, AppConfig.json and the org-ui blocks were already written.
$assetSaved = $script:ASSET
$script:ASSET = Join-Path $TMP 'Templates\ContosoBrokenExt'
New-Item -ItemType Directory -Path (Join-Path $script:ASSET 'Hooks') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $script:ASSET 'PSAppDeployToolkit.X') -Force | Out-Null
Set-Content -LiteralPath (Join-Path $script:ASSET 'Hooks\PreInstall.ps1') -Value "Write-ADTLogEntry -Message 'hook'" -Encoding UTF8
Set-Content -LiteralPath (Join-Path $script:ASSET 'PSAppDeployToolkit.X\PSAppDeployToolkit.X.psm1') -Value 'function Get-X { 1 }' -Encoding UTF8
try {
    foreach ($g in 'psadt-4.1.8', 'psadt-4.2.0-zeroconfig') {
        $p = New-Project $g "broken-ext-$g"
        $h = Get-ProjectHash $p
        $r = Invoke-Apply $p (New-Template @{ Hooks = [pscustomobject]@{ Enabled = $true; FailureAction = 'Fail' }; ExtensionModule = $true })
        $same = ((Get-ProjectHash $p) -join ',') -eq ($h -join ',')
        if ($r.Fqid -eq 'W32T.OrgExtensionInvalid' -and $same -and -not (Test-Path (Join-Path $p 'SupportFiles\OrgHooks')) -and -not (Test-Path (Join-Path $p 'PSAppDeployToolkit.X'))) {
            Ok "$g : psm1-only extension module -> W32T.OrgExtensionInvalid; deploy script, config.psd1, strings.psd1, AppConfig.json byte-identical; no hooks or module copied"
        } else { Bad "$g : fqid='$($r.Fqid)' unchanged=$same hooks=$(Test-Path (Join-Path $p 'SupportFiles\OrgHooks')) module=$(Test-Path (Join-Path $p 'PSAppDeployToolkit.X')) $($r.Message)" }
    }
}
finally { $script:ASSET = $assetSaved }

foreach ($c in @(@{ N = 'legacy-1.1.6-org'; G = 'legacy-1.1.6-org' }, @{ N = 'legacy-1.1.6-auto'; G = 'legacy-1.1.6-auto' }, @{ N = 'unpatched 4.2 Zero-Config golden'; G = 'psadt-4.2.0-zeroconfig' }, @{ N = 'unpatched 4.2 default golden'; G = 'psadt-4.2.0' })) {
    $p = New-Project $c.G ('refuse-' + ($c.N -replace '\W', '')) -NoGenerate
    $h = Get-ProjectHash $p
    $r = Invoke-Apply $p (New-Template @{ Hooks = [pscustomobject]@{ Enabled = $true; FailureAction = 'Fail' } })
    if ($r.Fqid -eq 'W32T.UnsupportedTemplateShape' -and $r.Message.StartsWith('Unsupported PSADT template shape: ') -and $r.Message.EndsWith('Nothing was changed.') -and $r.Message -match 'GeneratorVersion') {
        Ok "$($c.N) -> W32T.UnsupportedTemplateShape (C-1 wording, GeneratorVersion hint)"
    } else { Bad "$($c.N) -> fqid='$($r.Fqid)' $($r.Message)" }
    if (((Get-ProjectHash $p) -join ',') -eq ($h -join ',') -and -not (Test-Path (Join-Path $p 'SupportFiles\OrgHooks'))) { Ok "$($c.N): deploy script, config.psd1, strings.psd1, AppConfig.json byte-identical; no hooks copied" } else { Bad "$($c.N): a file was changed" }
}

# -- [6] typographic single quotes in strings.psd1 text; the psd1 gate (security-02) ------------------
Write-Host '[6] typographic single quotes round-trip through strings.psd1; a psd1 that would not parse is refused' -ForegroundColor Cyan
# U+2018/U+2019/U+201A/U+201B end a '...' literal under 5.1 and 7 just like the apostrophe; escaping only
# ' broke strings.psd1 (every deployment failed). Source stays ASCII: [char] builds them.
$balloon = 'C' + [char]0x2019 + 'est fait'
$progress = 'Installation de l' + [char]0x2019 + 'app ' + [char]0x2018 + 'x' + [char]0x201A + [char]0x201B + " 'y'"
foreach ($g in 'psadt-4.1.8', 'psadt-4.2.0-zeroconfig') {
    $p = New-Project $g "typo-$g"
    $r = Invoke-Apply $p (New-Template @{ CompanyName = 'L' + [char]0x2019 + 'Atelier IT'
            BalloonComplete = [pscustomobject]@{ Install = $balloon; Repair = 'Repaired.'; Uninstall = 'Removed.' }
            ProgressMessage = [pscustomobject]@{ Install = $progress; Repair = 'Repairing.'; Uninstall = 'Removing.' } })
    $sp = Join-Path $p 'Strings\strings.psd1'
    $se = $null
    [void][System.Management.Automation.Language.Parser]::ParseFile($sp, [ref]$null, [ref]$se)
    $s51 = @(Test-Win32ToolkitPS51Syntax -Path $sp)
    if ($r.Result -eq $true -and @($se).Count -eq 0 -and $s51.Count -eq 0) { Ok "$g : applied; strings.psd1 parses with 0 errors (host + Windows PowerShell 5.1)" } else { Bad "$g : result=$($r.Result) $($r.Fqid) $($r.Message) host=$(@($se).Count) 5.1=[$($s51 -join '; ')]" }
    $data = Import-PowerShellDataFile -LiteralPath $sp
    if ($data.BalloonTip.Complete.Install -ceq $balloon -and $data.ProgressPrompt.Message.Install -ceq $progress) { Ok "$g : BalloonComplete.Install and ProgressMessage.Install round-trip exactly" } else { Bad "$g : balloon=[$($data.BalloonTip.Complete.Install)] progress=[$($data.ProgressPrompt.Message.Install)]" }
}

# The gate itself: a config.psd1 / strings.psd1 text that does not parse to ONE hashtable is refused
# before the first write (shadowed sparse-config generator returns broken text).
foreach ($c in @(@{ N = 'unterminated hashtable'; T = "@{`r`n    Toolkit = @{ CompanyName = 'x' }`r`n" }, @{ N = 'not a hashtable'; T = "'just a string'`r`n" })) {
    $p = New-Project 'psadt-4.2.0-zeroconfig' ('psd1gate-' + ($c.N -replace '\W', ''))
    $h = Get-ProjectHash $p
    $script:BrokenPsd1 = $c.T
    function New-Win32ToolkitSparseConfig { param($Template) $script:BrokenPsd1 }
    try { $r = Invoke-Apply $p (New-Template) }
    finally { function New-Win32ToolkitSparseConfig { param($Template) "@{`r`n    Toolkit = @{`r`n        CompanyName = '$(ConvertTo-PSSingleQuoted ([string]$Template.CompanyName))'`r`n    }`r`n}`r`n" } }
    if ($r.Fqid -eq 'W32T.OrgTemplateInvalid' -and $r.Message -match 'config\.psd1 invalid PowerShell data' -and ((Get-ProjectHash $p) -join ',') -eq ($h -join ',')) {
        Ok "config.psd1 $($c.N) -> W32T.OrgTemplateInvalid; deploy script, config.psd1, strings.psd1, AppConfig.json byte-identical"
    } else { Bad "$($c.N): fqid='$($r.Fqid)' $($r.Message)" }
}

Remove-Item -LiteralPath $TMP -Recurse -Force -ErrorAction SilentlyContinue
Write-Host ''
if ($fail -eq 0) { Write-Host 'OrgUiBlocks unit test PASSED' -ForegroundColor Green; exit 0 }
Write-Host "$fail FAILURE(S)" -ForegroundColor Red
exit 1
